@startuml

class Researcher {
  + name : string
  + surname : string
  + group : ResearchGroup
  + wpAssignments : WorkPackage[]
}

class ResearchGroup {
  + name : string
  + department : Department
  + wps : WorkPackage[]
}

class Department {
  + name : string
}

class WorkPackage {
  + id : int
  + title : string
  + leader : ResearchGroup
  + members : Researcher[]
}

Researcher "1" -- "0..*" WorkPackage : assignedTo
Researcher "1" -- "1" ResearchGroup : belongsTo
ResearchGroup "1" *-- "1..*" WorkPackage : leads
Department "1" *-- "1..*" ResearchGroup : contains

@enduml

